<script setup lang="ts">import { computed,onMounted,ref } from 'vue'; import { BadgeCheck,Pencil,Plus,Trash2 } from '@lucide/vue'; import UiAlert from '../../../components/ui/UiAlert.vue'; import UiBadge from '../../../components/ui/UiBadge.vue'; import UiButton from '../../../components/ui/UiButton.vue'; import UiCard from '../../../components/ui/UiCard.vue'; import UiEmptyState from '../../../components/ui/UiEmptyState.vue'; import UiLoadingState from '../../../components/ui/UiLoadingState.vue'; import UiPagination from '../../../components/ui/UiPagination.vue'; import ConfirmDialog from '../../../components/shared/ConfirmDialog.vue'; import PageHeader from '../../../components/shared/PageHeader.vue'; import { countryName } from '../../../constants/countries'; import { useAuthStore } from '../../../stores/auth'; import { useBrandCatalog } from '../composables/useBrandCatalog'; import { useBrandForm } from '../composables/useBrandForm'; import type { Brand } from '../types/brand.types'; import BrandFormDialog from './BrandFormDialog.vue'; const auth=useAuthStore(); const catalog=useBrandCatalog(); const { brands, pagination, error, loading, load, loadAfterDeletion, removeBrand, saveBrand }=catalog; const editor=useBrandForm(saveBrand,load); const { open, title, busy: saving, error: formError, form, show, close, updateName, updateSlug, submit }=editor; const deleting=ref<Brand|null>(null); const busy=ref(false); const canManage=computed(()=>auth.hasPermission('catalog.manage')); async function remove(){if(!deleting.value)return;busy.value=true;try{await removeBrand(deleting.value.id);deleting.value=null;await loadAfterDeletion()}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось удалить бренд.'}finally{busy.value=false}} onMounted(load)</script>
<template><section class="mx-auto admin-page"><PageHeader class="mb-7" eyebrow="Каталог" title="Бренды"><template #actions><UiButton v-if="canManage" @click="show()"><Plus :size="18"/>Добавить бренд</UiButton></template></PageHeader><UiAlert v-if="error" class="mb-4">{{error}}</UiAlert><UiCard class="overflow-hidden"><UiLoadingState v-if="loading" label="Загрузка брендов…"/><div v-else-if="brands.length" class="divide-y"><article v-for="brand in brands" :key="brand.id" class="flex flex-wrap items-start gap-3 p-4 sm:flex-nowrap sm:items-center"><BadgeCheck class="shrink-0 text-primary-600"/><div class="min-w-0 flex-[1_1_calc(100%-52px)] sm:flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class="break-words font-semibold">{{brand.name}}</h2><UiBadge :tone="brand.is_active ? 'success' : 'neutral'">{{brand.is_active ? 'Активен' : 'Скрыт'}}</UiBadge></div><p class="break-words text-sm text-gray-500">/{{brand.slug}} · {{countryName(brand.country_code??'')}}</p></div><div v-if="canManage" class="ml-[52px] flex sm:ml-0"><UiButton variant="ghost" size="sm" :aria-label="`Редактировать бренд ${brand.name}`" @click="show(brand)"><Pencil :size="17"/></UiButton><UiButton variant="ghost" size="sm" :aria-label="`Удалить бренд ${brand.name}`" @click="deleting=brand"><Trash2 :size="17"/></UiButton></div></article></div><UiEmptyState v-else label="Брендов пока нет."/></UiCard><UiPagination v-if="pagination" :meta="pagination" :loading="loading" @change="load"/><BrandFormDialog :open="open" :title="title" :busy="saving" :error="formError" :form="form" @close="close" @submit="submit" @update-name="updateName" @update-slug="updateSlug"/><ConfirmDialog :open="Boolean(deleting)" title="Удалить бренд?" :description="`Бренд «${deleting?.name??''}» будет удалён.`" :busy="busy" @close="deleting=null" @confirm="remove"/></section></template>
